#include <stdio.h>
#include <string.h>

typedef struct {
    int id;
    char name[24];
    int score;
    int is_active;
} Record;

static Record database[1005];
static int total_records = 0;

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;

    char cmd[32];
    for (int i = 0; i < q; i++) {
        if (scanf("%31s", cmd) != 1) break;

        if (strcmp(cmd, "INSERT") == 0) {
            int id, score;
            char name[24];
            scanf("%d %23s %d", &id, name, &score);
            database[total_records].id = id;
            strncpy(database[total_records].name, name, 23);
            database[total_records].name[23] = '\0';
            database[total_records].score = score;
            database[total_records].is_active = 1;
            total_records++;
        } else if (strcmp(cmd, "READ") == 0) {
            int idx;
            scanf("%d", &idx);
            if (idx >= 0 && idx < total_records && database[idx].is_active) {
                printf("ID: %d, Name: %s, Score: %d\n", database[idx].id, database[idx].name, database[idx].score);
            } else {
                printf("RECORD NOT FOUND\n");
            }
        } else if (strcmp(cmd, "UPDATE") == 0) {
            int idx, new_score;
            scanf("%d %d", &idx, &new_score);
            if (idx >= 0 && idx < total_records && database[idx].is_active) {
                database[idx].score = new_score;
                printf("RECORD UPDATED\n");
            } else {
                printf("UPDATE FAILED\n");
            }
        } else if (strcmp(cmd, "DELETE") == 0) {
            int idx;
            scanf("%d", &idx);
            if (idx >= 0 && idx < total_records && database[idx].is_active) {
                database[idx].is_active = 0;
                printf("RECORD DELETED\n");
            } else {
                printf("DELETE FAILED\n");
            }
        }
    }

    return 0;
}

