#include <stdio.h>
#include <string.h>

#define MAX_LINE 4096

static void trim_trailing_newline(char *s) {
    size_t len = strlen(s);
    while (len > 0 && (s[len - 1] == '\n' || s[len - 1] == '\r')) {
        s[len - 1] = '\0';
        len--;
    }
}

static void parse_csv_line(const char *line, int line_num) {
    printf("Line %d:\n", line_num);

    char field[MAX_LINE];
    int field_idx = 0;
    int out_pos = 0;
    int in_quotes = 0;
    int len = (int)strlen(line);

    for (int i = 0; i <= len; i++) {
        char c = line[i];

        if (in_quotes) {
            if (c == '"') {
                if (line[i + 1] == '"') {
                    // Escaped quote: "" -> "
                    field[out_pos++] = '"';
                    i++;
                } else {
                    // Closing quote
                    in_quotes = 0;
                }
            } else {
                field[out_pos++] = c;
            }
        } else {
            if (c == '"') {
                // Opening quote
                in_quotes = 1;
            } else if (c == ',' || c == '\0') {
                // End of field
                field[out_pos] = '\0';
                printf("Field %d: %s\n", field_idx++, field);
                out_pos = 0;
            } else {
                field[out_pos++] = c;
            }
        }
    }
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    // Consume newline after n
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF);

    char line[MAX_LINE];
    for (int i = 1; i <= n; i++) {
        if (!fgets(line, sizeof(line), stdin)) break;
        trim_trailing_newline(line);
        parse_csv_line(line, i);
    }

    return 0;
}

