#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

static int eval_operand(const char *expr, int *pX, int *pY) {
    while (*expr == ' ') expr++;
    if (strcmp(expr, "X++") == 0) {
        int val = *pX;
        (*pX)++;
        return val;
    } else if (strcmp(expr, "Y++") == 0) {
        int val = *pY;
        (*pY)++;
        return val;
    } else if (strcmp(expr, "X") == 0) {
        return *pX;
    } else if (strcmp(expr, "Y") == 0) {
        return *pY;
    } else {
        return atoi(expr);
    }
}

static void trim_trailing(char *s) {
    size_t len = strlen(s);
    while (len > 0 && (s[len - 1] == ' ' || s[len - 1] == '\n' || s[len - 1] == '\r')) {
        s[len - 1] = '\0';
        len--;
    }
}

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;

    char line[512];
    // Consume newline
    fgets(line, sizeof(line), stdin);

    for (int i = 0; i < q; i++) {
        if (!fgets(line, sizeof(line), stdin)) break;
        trim_trailing(line);
        if (strlen(line) == 0) continue;

        int x = 0, y = 0;
        char *semicolon = strchr(line, ';');
        if (!semicolon) continue;

        *semicolon = '\0';
        sscanf(line, "INIT %d %d", &x, &y);

        char *max_part = semicolon + 1;
        while (*max_part == ' ') max_part++;

        char *open_paren = strchr(max_part, '(');
        char *close_paren = strrchr(max_part, ')');
        if (!open_paren || !close_paren || open_paren >= close_paren) continue;

        *close_paren = '\0';
        char *inner = open_paren + 1;

        char *comma = strchr(inner, ',');
        if (!comma) continue;
        *comma = '\0';
        char *opA = inner;
        char *opB = comma + 1;

        trim_trailing(opA);
        while (*opB == ' ') opB++;
        trim_trailing(opB);

        // Evaluate strictly once from left to right
        int valA = eval_operand(opA, &x, &y);
        int valB = eval_operand(opB, &x, &y);
        int max_val = (valA > valB) ? valA : valB;

        printf("RESULT: %d, X: %d, Y: %d\n", max_val, x, y);
    }

    return 0;
}

