#include <stdio.h>
#include <string.h>

#define MAX_SYMBOLS 1000

typedef struct {
    char name[36];
    int def_count;
} DefEntry;

static DefEntry defs[MAX_SYMBOLS];
static int def_total = 0;

typedef struct {
    char name[36];
} RefEntry;

static RefEntry refs[MAX_SYMBOLS];
static int ref_total = 0;

static int find_def(const char *name) {
    for (int i = 0; i < def_total; i++) {
        if (strcmp(defs[i].name, name) == 0) return i;
    }
    return -1;
}

int main(void) {
    int f;
    if (scanf("%d", &f) != 1) return 0;

    char mult_def_symbol[36] = "";
    int has_mult_def = 0;

    for (int file_idx = 0; file_idx < f; file_idx++) {
        char filename[64];
        int s;
        scanf("%63s %d", filename, &s);

        for (int j = 0; j < s; j++) {
            char linkage[20], name[36];
            scanf("%19s %35s", linkage, name);

            if (strcmp(linkage, "DEF") == 0) {
                int idx = find_def(name);
                if (idx != -1) {
                    defs[idx].def_count++;
                    if (!has_mult_def) {
                        strncpy(mult_def_symbol, name, 35);
                        has_mult_def = 1;
                    }
                } else {
                    strncpy(defs[def_total].name, name, 35);
                    defs[def_total].def_count = 1;
                    def_total++;
                }
            } else if (strcmp(linkage, "EXTERN_REF") == 0) {
                strncpy(refs[ref_total].name, name, 35);
                ref_total++;
            }
            // STATIC_DEF is ignored globally as it is internal to the translation unit
        }
    }

    if (has_mult_def) {
        printf("ERROR: MULTIPLE_DEFINITION %s\n", mult_def_symbol);
        return 0;
    }

    for (int i = 0; i < ref_total; i++) {
        if (find_def(refs[i].name) == -1) {
            printf("ERROR: UNDEFINED_REFERENCE %s\n", refs[i].name);
            return 0;
        }
    }

    printf("LINK SUCCESS: %d EXTERNAL SYMBOLS\n", def_total);
    return 0;
}
